<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\LoadService;use App\Security\Csrf;use App\Support\Url;Auth::requirePermission('LOAD_CREATE_OWN');$errors=[];$values=$_POST;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';else try{$id=LoadService::create($_POST,(int)Auth::user()['id']);header('Location: '.Url::to('loads/view.php?id='.$id.'&created=1'));exit;}catch(RuntimeException$e){$errors[]=$e->getMessage();}catch(Throwable$e){@file_put_contents(BASE_PATH.'/storage/logs/phase4.log','['.date('c').'] '.$e->getMessage().PHP_EOL,FILE_APPEND|LOCK_EX);$errors[]='The draft could not be created. Check the local error log.';}}$pageTitle='Post a Load';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Post a Load</h1><p>Create a company-scoped draft. You may review it before submission.</p></div></div><?php foreach($errors as$e):?><div class="error"><?=h($e)?></div><?php endforeach;?><form class="card" method="post"><input type="hidden" name="_csrf" value="<?=h(Csrf::token())?>"><?php require BASE_PATH.'/app/Views/loads/form.php';?><div class="actions"><button class="button">Save draft</button><a class="button secondary" href="<?=h(Url::to('loads/index.php'))?>">Cancel</a></div></form><?php require BASE_PATH.'/app/Views/layout/footer.php';
